6	/** Strong references cover acquisition as well as the acquired lock. */
7	const heldLocks = new Set<DatabaseSync>()
8	
9	export class SqliteLockBusy extends Error {
10	  override readonly name = 'SqliteLockBusy'
11	}
12	export class SqliteLockIncomplete extends StorageDefect {
13	  constructor(cause?: unknown) {
14	    super('coordination database remains open; ownership is retained', { cause })
15	  }
16	}
17	export interface SqliteOwnerLock extends OwnerLock {
18	  readonly released: boolean
19	}
20	
21	/** Private empty coordination database, never a production data connection. */
22	export function acquireSqliteLock(file: string): SqliteOwnerLock {
23	  const db = new DatabaseSync(file, { timeout: 0 })
24	  heldLocks.add(db)
25	  const close = () => {
26	    let failed = false,
27	      failure: unknown
28	    try {
29	      db.close()
30	    } catch (error) {
31	      failed = true
32	      failure = error
33	    }
34	    if (db.isOpen) throw new SqliteLockIncomplete(failure)
35	    heldLocks.delete(db)
36	    if (failed) throw failure
37	  }
38	  try {
39	    db.exec('PRAGMA journal_mode = MEMORY')
40	    db.exec('BEGIN IMMEDIATE')
41	  } catch (error) {
42	    try {
43	      close()
44	    } catch (cleanup) {
45	      const combined = new AggregateError(
46	        [error, cleanup],
47	        'coordination acquisition and cleanup failed',
48	      )
49	      if (db.isOpen) throw new SqliteLockIncomplete(combined)
50	      throw combined
51	    }
52	    if (isSqliteBusy(error)) throw new SqliteLockBusy('coordination lock is occupied')
53	    throw error
54	  }
55	  return {
56	    get released() {
57	      return !db.isOpen
58	    },
59	    async release() {
60	      if (!db.isOpen) return
61	      // Native close ends the empty transaction. Do not release exclusion with an
62	      // earlier ROLLBACK while native close can still fail with the handle open.
63	      close()
64	    },
65	  }
66	}
