4	interface Resource {
5	  readonly close: () => void | Promise<void>
6	  readonly isClosed?: () => boolean
7	  pending: Promise<void> | undefined
8	}
9	
10	/** A failed close must not let GC silently discard the remaining resource owner. */
11	const retainedScopes = new Set<SnapshotResources>()
12	
13	export class SnapshotResources {
14	  readonly #resources = new Set<Resource>()
15	  #accepting = true
16	  #closeFailed = false
17	  #failure: unknown
18	
19	  get closeFailed(): boolean {
20	    return this.#closeFailed
21	  }
22	
23	  assertClean(): void {
24	    if (this.#closeFailed) throw this.#failure
25	  }
26	
27	  get settled(): boolean {
28	    return this.#resources.size === 0
29	  }
30	
31	  own(close: () => void | Promise<void>, isClosed?: () => boolean): () => Promise<void> {
32	    if (!this.#accepting) throw new StorageDefect('snapshot resource scope has ended')
33	    const resource: Resource = {
34	      close,
35	      pending: undefined,
36	      ...(isClosed === undefined ? {} : { isClosed }),
37	    }
38	    this.#resources.add(resource)
39	    retainedScopes.add(this)
40	    return () => this.#release(resource)
41	  }
42	
43	  #forget(resource: Resource): void {
44	    this.#resources.delete(resource)
45	    if (this.settled) retainedScopes.delete(this)
46	  }
47	
48	  #release(resource: Resource): Promise<void> {
49	    if (!this.#resources.has(resource)) return Promise.resolve()
50	    resource.pending ??= (async () => {
51	      try {
52	        await resource.close()
53	        if (resource.isClosed?.() === false)
54	          throw new StorageDefect('resource close returned while still open')
55	        this.#forget(resource)
56	      } catch (error) {
57	        this.#failure = this.#closeFailed ? combineFailure(this.#failure, error) : error
58	        this.#closeFailed = true
59	        // Some APIs can throw after the resource has actually closed. Preserve the
60	        // error, but use an explicit API observation rather than guessing ownership.
61	        if (resource.isClosed?.() === true) this.#forget(resource)
62	        throw error
63	      }
64	    })().finally(() => {
65	      resource.pending = undefined
66	    })
67	    return resource.pending
68	  }
69	
70	  /** Retry is explicit resource cleanup; it never replays an export or publication. */
71	  async close(): Promise<void> {
72	    this.#accepting = false
73	    let firstFailure: unknown
74	    let failed = false
75	    for (const resource of [...this.#resources].reverse()) {
76	      try {
77	        await this.#release(resource)
78	      } catch (error) {
79	        firstFailure = failed ? combineFailure(firstFailure, error) : error
80	        failed = true
81	      }
82	    }
83	    if (failed) throw firstFailure
84	  }
85	}
