104	export class NodeSqliteDriver implements Driver {
105	  readonly #native = new Set<DatabaseSync>()
106	  get resourcesClosed(): boolean {
107	    return [...this.#native].every(db => !db.isOpen)
108	  }
109	  #writer: NodeSqliteConnection | undefined
110	  #readers: NodeSqliteConnection[] = []
111	  #openReaders = 0
112	  #readerWaiters: ((c: DatabaseConnection) => void)[] = []
113	  #writeQueue: Promise<void> = Promise.resolve()
114	  #closed = false
