119	  async init(): Promise<void> {
120	    if (this.options.role === 'write') {
121	      this.#writer = new NodeSqliteConnection(this.#open('write'), 'write', this.#resolver)
122	    } else {
123	      // 读句柄按需开；这里开一个以便打开失败在启动期暴露
124	      this.#readers.push(new NodeSqliteConnection(this.#open('read'), 'read', this.#resolver))
125	      this.#openReaders = 1
126	    }
127	  }
128	
129	  #open(role: 'write' | 'read'): DatabaseSync {
130	    assertProductionStoragePath(this.options.file)
131	    const db = new DatabaseSync(this.options.file, {
132	      enableForeignKeyConstraints: true,
133	      timeout: role === 'write' ? 0 : 5000,
134	    })
135	    this.#native.add(db)
136	    try {
137	      db.exec('PRAGMA journal_mode = WAL')
138	      db.exec(
139	        this.options.synchronous === 'full'
140	          ? 'PRAGMA synchronous = FULL'
141	          : 'PRAGMA synchronous = NORMAL',
142	      )
143	      db.exec('PRAGMA foreign_keys = ON')
144	      if (role === 'read') db.exec('PRAGMA query_only = ON')
145	      return db
146	    } catch (error) {
147	      // The pool does not own this handle until initialization succeeds.
148	      try {
149	        db.close()
150	      } catch (closing) {
151	        if (db.isOpen) retainedNativeHandles.add(db)
152	        throw new AggregateError([error, closing], 'sqlite initialization and cleanup failed')
153	      }
154	      throw error
155	    }
156	  }
157	
158	  async acquireConnection(): Promise<DatabaseConnection> {
159	    if (this.#closed) throw new StorageUnavailable('sqlite storage is closed')
160	    if (this.options.role === 'read') {
161	      const idle = this.#readers.pop()
162	      if (idle !== undefined) return idle
163	      if (this.#openReaders < MAX_READERS) {
164	        const connection = new NodeSqliteConnection(this.#open('read'), 'read', this.#resolver)
165	        this.#openReaders += 1
166	        return connection
167	      }
168	      // 到上限：排队等一个读句柄被释放
169	      return new Promise<DatabaseConnection>(resolve => this.#readerWaiters.push(resolve))
170	    }
171	    if (this.#writer === undefined) throw new StorageUnavailable('sqlite storage is closed')
172	    // 写：进程内队列，同一实例的多个 write 顺序共用一个句柄
173	    const previous = this.#writeQueue
174	    let release!: () => void
175	    this.#writeQueue = new Promise<void>(resolve => {
176	      release = resolve
177	    })
178	    await previous
179	    if (this.#closed || this.#writer === undefined) {
180	      release()
181	      throw new StorageUnavailable('sqlite storage is closed')
182	    }
183	    this.#writerRelease = release
184	    return this.#writer
185	  }
186	  #writerRelease: (() => void) | undefined
187	
188	  async beginTransaction(
189	    connection: DatabaseConnection,
190	    settings: TransactionSettings,
191	  ): Promise<void> {
192	    const c = connection as NodeSqliteConnection
193	    if (c.role === 'read') {
194	      c.db.exec('BEGIN')
195	      return
196	    }
