245	    const waiter = this.#readerWaiters.shift()
246	    if (waiter !== undefined) {
247	      waiter(c)
248	      return
249	    }
250	    this.#readers.push(c)
251	  }
252	
253	  /** 关准入 → 等在途写排空 → 关全部句柄。 */
